double h = fabs(b - a);
double m = (a + b) / 2.0;
double old_integral = h * f(m);
double h_new = h / 2.0;

int N = 2;
while (true) {
    double new_integral = 0;
    for (int i = 0; i < N; i++) {
        double x_left = a + i * h_new;
        double x_mid = x_left + h_new / 2.0;
        new_integral += f(x_mid) * h_new;
    }

    if (fabs(new_integral - old_integral) < precision) {
        return new_integral;
    }

    old_integral = new_integral;
    h_new = h_new / 2.0;
    N = N * 2;
}

